  ctx.fillStyle=UIC.tx_1;
  ctx.beginPath(); ctx.arc(qx,qy,(mapFirstOn()?1.6:2.6)*_MZ,0,6.2832); ctx.fill();
  mapIcon(qx,qy,(mapFirstOn()?7:13)*_MZ);
