  if(!mapFirstOn()) mapLabel(CQ.opened?'LOOTED':'CACHE',qx,qy-20*_MZ,UIC.tx_1,null,qy);   // v28.xx (cw-cx-sectorhold-o03): one label per cache, including the two inside a locked room.
  ctx.globalAlpha=1;
}
